// 컴파일된 컴포넌트 라이브러리 흉내(R143 재현): jsx-runtime 사용, 내부 레이어 ButtonBase 1개 — 경로에 node_modules/가 있어야 어댑터·서버 필터가 라이브러리로 본다
import { jsx } from 'react/jsx-runtime';
function ButtonBase(props) { return jsx('button', { ...props, className: 'FakeButtonBase-root' }); }
export function Button(props) { return jsx(ButtonBase, { ...props, className: 'FakeButton-root' }); }
